"use server";

import { createServerClient } from '@supabase/ssr';
import { cookies } from 'next/headers';

export async function getPPIDashboardStats() {
  const cookieStore = await cookies();
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    { cookies: { getAll() { return cookieStore.getAll() } } }
  );

  const now = new Date();
  const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
  const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];

  const { data, error } = await supabase
    .from('surveilans_harian')
    .select(`
      *,
      master_ruangan (nama_ruangan)
    `)
    .gte('tanggal', firstDay)
    .lte('tanggal', lastDay);

  if (error || !data) return null;

  // Hitung HAIs Global
  const totalHais = data.filter(r => 
    Number(r.vap) === 1 || Number(r.hap) === 1 || Number(r.isk) === 1 || Number(r.iad) === 1
  ).length;

  // Hitung Data Belum Terverifikasi
  const belumVerif = data.filter(r => r.is_verified === false).length;

  return {
    totalHais,
    belumVerif,
    totalEntries: data.length,
    data
  };
}